INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_059_M6_S1', 'process evaluation', '1', 'process evaluation: Assessment of how a policy or programme was implemented, including whether activities reached intended participants and followed the planned delivery process. In Policy Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of process evaluation within Public Policy and Governance, particularly where the Policy Evaluation module establishes its technical context.', 'SSD_COURSE_059_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M6_S2', 'outcome evaluation', '2', 'outcome evaluation: Assessment of whether a policy or programme produced its intended outcomes and the extent to which observed changes can reasonably be attributed to the intervention. In Policy Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of outcome evaluation within Public Policy and Governance, particularly where the Policy Evaluation module establishes its technical context.', 'SSD_COURSE_059_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M6_S3', 'impact evaluation', '3', 'impact evaluation: Evaluation designed to estimate whether and to what extent an intervention caused observed changes in specified outcomes, using an appropriate counterfactual or identification strategy. In Policy Evaluation, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_059_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M6_S4', 'cost-effectiveness', '4', 'cost-effectiveness: Comparison of alternative interventions according to the outcomes achieved for a given level of resources or cost. In Policy Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of cost-effectiveness within Public Policy and Governance, particularly where the Policy Evaluation module establishes its technical context.', 'SSD_COURSE_059_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M7_S1', 'digital public services', '1', 'digital public services: Government services delivered or supported through digital platforms, systems, and data. In Digital Governance and Contemporary Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of digital public services within Public Policy and Governance, particularly where the Digital Governance and Contemporary Policy module establishes its technical context.', 'SSD_COURSE_059_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M7_S2', 'data governance', '2', 'data governance: data governance in Public Policy and Governance concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing data governance. In Digital Governance and Contemporary Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of data governance within Public Policy and Governance, particularly where the Digital Governance and Contemporary Policy module establishes its technical context.', 'SSD_COURSE_059_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M7_S3', 'algorithmic decision-making', '3', 'algorithmic decision-making: Use of computational rules or models to support or make decisions affecting public services, rights, or resource allocation. In Digital Governance and Contemporary Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of algorithmic decision-making within Public Policy and Governance, particularly where the Digital Governance and Contemporary Policy module establishes its technical context.', 'SSD_COURSE_059_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M7_S4', 'platform regulation', '4', 'platform regulation: Rules and oversight mechanisms governing digital platforms, including issues such as competition, content, data, consumer protection, and platform accountability. In Digital Governance and Contemporary Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of platform regulation within Public Policy and Governance, particularly where the Digital Governance and Contemporary Policy module establishes its technical context.', 'SSD_COURSE_059_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M1_S1', 'research questions', '1', 'research questions: Clearly stated questions that define what a social-science study seeks to investigate or explain. In Research Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of research questions within Research Methods in Social Sciences, particularly where the Research Design module establishes its technical context.', 'SSD_COURSE_060_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M1_S2', 'theory and hypotheses', '2', 'theory and hypotheses: Conceptual explanations and testable propositions linking variables, mechanisms, or expected relationships. In Research Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of theory and hypotheses within Research Methods in Social Sciences, particularly where the Research Design module establishes its technical context.', 'SSD_COURSE_060_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M1_S3', 'exploratory/descriptive/explanatory designs', '3', 'exploratory/descriptive/explanatory designs: Research designs used respectively to explore a poorly understood issue, describe characteristics or patterns, or test explanations for observed relationships. In Research Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of exploratory/descriptive/explanatory designs within Research Methods in Social Sciences, particularly where the Research Design module establishes its technical context.', 'SSD_COURSE_060_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M2_S1', 'probability sampling', '1', 'probability sampling: Sampling in which each eligible population unit has a known, non-zero probability of selection. In Sampling and Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of probability sampling within Research Methods in Social Sciences, particularly where the Sampling and Measurement module establishes its technical context.', 'SSD_COURSE_060_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M2_S2', 'non-probability sampling', '2', 'non-probability sampling: Sampling methods in which selection probabilities are not known or are not based on random selection. In Sampling and Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of non-probability sampling within Research Methods in Social Sciences, particularly where the Sampling and Measurement module establishes its technical context.', 'SSD_COURSE_060_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M2_S3', 'measurement scales', '3', 'measurement scales: Levels of measurement—nominal, ordinal, interval, and ratio—that determine what comparisons and statistical operations are appropriate for a variable. In Sampling and Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of measurement scales within Research Methods in Social Sciences, particularly where the Sampling and Measurement module establishes its technical context.', 'SSD_COURSE_060_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M2_S4', 'instrument design', '4', 'instrument design: Designing questionnaires, interview schedules, tests, or other measurement instruments so that constructs are measured clearly, consistently, and appropriately. In Sampling and Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of instrument design within Research Methods in Social Sciences, particularly where the Sampling and Measurement module establishes its technical context.', 'SSD_COURSE_060_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M3_S1', 'interviews', '1', 'interviews: Structured, semi-structured, or open conversations used to collect participants'' accounts, experiences, or views. In Qualitative Methods, the focus is on the analysis, design, implementation, interpretation, or evaluation of interviews within Research Methods in Social Sciences, particularly where the Qualitative Methods module establishes its technical context.', 'SSD_COURSE_060_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M3_S2', 'focus groups', '2', 'focus groups: Moderated group discussions used to explore shared views, differences, meanings, and interaction around a research topic. In Qualitative Methods, the focus is on the analysis, design, implementation, interpretation, or evaluation of focus groups within Research Methods in Social Sciences, particularly where the Qualitative Methods module establishes its technical context.', 'SSD_COURSE_060_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M3_S3', 'observation', '3', 'observation: Systematic recording of behaviour, interactions, settings, or events as research data. In Qualitative Methods, the focus is on the analysis, design, implementation, interpretation, or evaluation of observation within Research Methods in Social Sciences, particularly where the Qualitative Methods module establishes its technical context.', 'SSD_COURSE_060_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M3_S4', 'ethnography', '4', 'ethnography: In-depth study of people and social practices through sustained engagement and observation in a social setting. In Qualitative Methods, the focus is on the analysis, design, implementation, interpretation, or evaluation of ethnography within Research Methods in Social Sciences, particularly where the Qualitative Methods module establishes its technical context.', 'SSD_COURSE_060_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M3_S5', 'thematic analysis', '5', 'thematic analysis refers to a qualitative method for systematically coding data and developing themes that capture recurring patterns of meaning. In Qualitative Methods, the focus is on the analysis, design, implementation, interpretation, or evaluation of thematic analysis within Research Methods in Social Sciences, particularly where the Qualitative Methods module establishes its technical context.', 'SSD_COURSE_060_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M4_S1', 'descriptive statistics', '1', 'descriptive statistics: Methods for summarising and presenting data using measures such as frequencies, means, medians, and dispersion. In Quantitative Methods and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of descriptive statistics within Research Methods in Social Sciences, particularly where the Quantitative Methods and Data Analysis module establishes its technical context.', 'SSD_COURSE_060_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M4_S2', 'regression', '2', 'regression: Statistical modelling of relationships between an outcome variable and one or more explanatory variables. In Quantitative Methods and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of regression within Research Methods in Social Sciences, particularly where the Quantitative Methods and Data Analysis module establishes its technical context.', 'SSD_COURSE_060_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M4_S3', 'hypothesis testing', '3', 'hypothesis testing: Statistical procedures for evaluating evidence against a null or reference hypothesis using a specified test statistic, significance level, and sampling model. In Quantitative Methods and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of hypothesis testing within Research Methods in Social Sciences, particularly where the Quantitative Methods and Data Analysis module establishes its technical context.', 'SSD_COURSE_060_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M4_S4', 'causal inference basics', '4', 'causal inference basics: Methods and assumptions used to distinguish causal effects from associations in observational or experimental data. In Quantitative Methods and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of causal inference basics within Research Methods in Social Sciences, particularly where the Quantitative Methods and Data Analysis module establishes its technical context.', 'SSD_COURSE_060_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M5_S1', 'sequential designs', '1', 'sequential designs: Mixed-methods designs in which one phase of qualitative or quantitative research is conducted before the next and informs its purpose or execution. In Mixed Methods and Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of sequential designs within Research Methods in Social Sciences, particularly where the Mixed Methods and Integration module establishes its technical context.', 'SSD_COURSE_060_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M5_S2', 'convergent designs', '2', 'convergent designs: Mixed-methods designs in which qualitative and quantitative data are collected in a broadly parallel phase and integrated to compare or complement findings. In Mixed Methods and Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of convergent designs within Research Methods in Social Sciences, particularly where the Mixed Methods and Integration module establishes its technical context.', 'SSD_COURSE_060_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M5_S3', 'triangulation', '3', 'triangulation: Using multiple data sources, methods, investigators, or perspectives to examine the consistency of research findings. In Mixed Methods and Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of triangulation within Research Methods in Social Sciences, particularly where the Mixed Methods and Integration module establishes its technical context.', 'SSD_COURSE_060_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M5_S4', 'integration', '4', 'integration: Systematic combination of qualitative and quantitative evidence so that the findings inform a common interpretation. In Mixed Methods and Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of integration within Research Methods in Social Sciences, particularly where the Mixed Methods and Integration module establishes its technical context.', 'SSD_COURSE_060_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M6_S1', 'construct validity', '1', 'construct validity refers to the extent to which an operational measure adequately represents the theoretical construct it is intended to measure. In Validity, Reliability and Research Quality, the focus is on the analysis, design, implementation, interpretation, or evaluation of construct validity within Research Methods in Social Sciences, particularly where the Validity, Reliability and Research Quality module establishes its technical context.', 'SSD_COURSE_060_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M6_S2', 'internal validity', '2', 'internal validity refers to the degree to which a study supports a credible causal interpretation for its observed results. In Validity, Reliability and Research Quality, the focus is on the analysis, design, implementation, interpretation, or evaluation of internal validity within Research Methods in Social Sciences, particularly where the Validity, Reliability and Research Quality module establishes its technical context.', 'SSD_COURSE_060_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M6_S3', 'external validity', '3', 'external validity refers to the extent to which study findings can reasonably apply beyond the sampled population, setting, or conditions. In Validity, Reliability and Research Quality, the focus is on the analysis, design, implementation, interpretation, or evaluation of external validity within Research Methods in Social Sciences, particularly where the Validity, Reliability and Research Quality module establishes its technical context.', 'SSD_COURSE_060_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M6_S4', 'reliability', '4', 'reliability: reliability in Research Methods in Social Sciences concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing reliability. In Validity, Reliability and Research Quality, the focus is on the analysis, design, implementation, interpretation, or evaluation of reliability within Research Methods in Social Sciences, particularly where the Validity, Reliability and Research Quality module establishes its technical context.', 'SSD_COURSE_060_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M6_S5', 'reflexivity', '5', 'reflexivity: Critical examination of how the researcher''s position, assumptions, relationships, and decisions may affect the research. In Validity, Reliability and Research Quality, the focus is on the analysis, design, implementation, interpretation, or evaluation of reflexivity within Research Methods in Social Sciences, particularly where the Validity, Reliability and Research Quality module establishes its technical context.', 'SSD_COURSE_060_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M7_S1', 'informed consent', '1', 'informed consent: Voluntary agreement to participate based on adequate information about the study, risks, benefits, and rights. In Research Ethics and Integrity, the focus is on the analysis, design, implementation, interpretation, or evaluation of informed consent within Research Methods in Social Sciences, particularly where the Research Ethics and Integrity module establishes its technical context.', 'SSD_COURSE_060_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M7_S2', 'Research confidentiality', '2', 'Research confidentiality: Protection of identifiable or sensitive research information from unauthorized access or disclosure, consistent with informed consent, ethics requirements, data-management plans, and applicable law. In Research Ethics and Integrity, the focus is on curricular scope: Research Methods in Social Sciences; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_060_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M7_S3', 'research ethics review', '3', 'research ethics review: Independent or institutional review of a study''s ethical acceptability, participant protections, and consent procedures. In Research Ethics and Integrity, the focus is on the analysis, design, implementation, interpretation, or evaluation of research ethics review within Research Methods in Social Sciences, particularly where the Research Ethics and Integrity module establishes its technical context.', 'SSD_COURSE_060_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M7_S4', 'data management', '4', 'data management: Processes for organising, storing, securing, documenting, preserving, and appropriately sharing research data. In Research Ethics and Integrity, the focus is on the analysis, design, implementation, interpretation, or evaluation of data management within Research Methods in Social Sciences, particularly where the Research Ethics and Integrity module establishes its technical context.', 'SSD_COURSE_060_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_060_M7_S5', 'reproducibility', '5', 'reproducibility refers to the ability to obtain consistent results when the same analysis, data, methods, and documented computational steps are repeated. In Research Ethics and Integrity, the focus is on the analysis, design, implementation, interpretation, or evaluation of reproducibility within Machine Learning, particularly where the Model Evaluation and Deployment module establishes its technical context.', 'SSD_COURSE_060_M7_S5', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;